package main

import (
	_ "embed"

	"github.com/nsgo-dev/game/packages/game/project"
)

// gameYAML is Lantern 3D's project file, holding its window size, appearance and export presets.
//
//go:embed game.yaml
var gameYAML []byte

// gameProject is the parsed game.yaml.
var gameProject = project.MustParse(gameYAML)

// lanternShrineGLB is the embedded binary glTF 2.0 diorama scene generated by tools/genassets/main.go (CC0-1.0, see CREDITS.md).
//
//go:embed assets/lantern_shrine.glb
var lanternShrineGLB []byte
